import{_ as e,o as r,c as t,ak as s}from"./chunks/framework.BHDkgpnK.js";const h=JSON.parse('{"title":"KossJS 诞生记","description":"","frontmatter":{},"headers":[],"relativePath":"zh/other/origin-story.md","filePath":"zh/other/origin-story.md","lastUpdated":0}'),a={name:"zh/other/origin-story.md"};function i(l,o,n,d,c,p){return r(),t("div",null,[...o[0]||(o[0]=[s('<h1 id="kossjs-诞生记" tabindex="-1">KossJS 诞生记 <a class="header-anchor" href="#kossjs-诞生记" aria-label="Permalink to “KossJS 诞生记”">​</a></h1><h2 id="缘起-一次不满-一个念头" tabindex="-1">缘起：一次不满，一个念头 <a class="header-anchor" href="#缘起-一次不满-一个念头" aria-label="Permalink to “缘起：一次不满，一个念头”">​</a></h2><p>2025年12月，开发者 <strong>星燃</strong> 在使用 KubeJS 时，接连遇到两个痛点：</p><ul><li>不直接支持 <code>fetch</code> 等现代 Web API；</li><li>迟迟没有高版本 Fabric 的适配。</li></ul><p>于是，一个大胆的想法浮现：</p><blockquote><p>“要不我自己做一个替代 KubeJS 的项目吧，就叫 <strong>KifeJS</strong>。”</p></blockquote><p>彼时的初步设想是：</p><ul><li>目标：替代 KubeJS</li><li>游戏版本：Minecraft 26.1.2</li><li>模组加载器：Fabric</li></ul><p>然而，星燃并不熟悉 Java，项目因此暂时搁置。</p><hr><h2 id="转向-从-替代模组-到-js-引擎" tabindex="-1">转向：从“替代模组”到“JS 引擎” <a class="header-anchor" href="#转向-从-替代模组-到-js-引擎" aria-label="Permalink to “转向：从“替代模组”到“JS 引擎””">​</a></h2><p>2026年3月1日，星燃调整了思路——与其直接做游戏模组，不如先实现一个通用的 JavaScript 引擎：</p><blockquote><p>“KossJS 项目目标：实现一个 Bun.js 那样的运行时。”</p></blockquote><p>接下来的十天（3月10日–20日），星燃进行技术选型，初步决定使用 <strong>Rust + v8</strong> 组合，并着手编写第一个版本。</p><p>但很快，他意识到不应仓促决定技术栈和目标定位。于是，在 3月20日–31日期间，他暂停编码，认真验证了项目的可行性，并重新明确了设计方向：</p><blockquote><p><strong>KossJS 项目设计（最终版）</strong></p><ul><li>目标：打造一个<strong>高性能、跨平台、嵌入式的 JavaScript 运行时引擎</strong></li><li>技术栈：<strong>Rust + Boa</strong>（纯 Rust 实现的 JS 引擎）</li></ul></blockquote><hr><h2 id="启程-从零到-dev-9" tabindex="-1">启程：从零到 dev.9 <a class="header-anchor" href="#启程-从零到-dev-9" aria-label="Permalink to “启程：从零到 dev.9”">​</a></h2><p>2026年3月31日，正式开发启动。</p><ul><li><strong>4月5日</strong>：首个版本 <code>dev.1</code> 上传至 GitHub</li><li><strong>4月6日</strong>：大量更新，实现 <code>dev.2</code></li><li><strong>4月12日</strong>：<code>dev.3</code> 实现</li><li><strong>4月13日</strong>：<code>dev.4</code> 实现</li><li><strong>5月14日</strong>：<code>dev.5</code> 实现</li><li><strong>6月3日</strong>：<code>dev.6</code> 实现</li><li><strong>6月21日</strong>：<code>dev.7</code> 实现</li><li><strong>6月25日</strong>：<code>dev.8</code> 实现</li><li><strong>7月12日</strong>：<code>dev.9</code> 实现，<strong>功能基本完备</strong>，虽然并未发布，但在等待第一批用户使用。</li></ul><hr><h2 id="现状与展望" tabindex="-1">现状与展望 <a class="header-anchor" href="#现状与展望" aria-label="Permalink to “现状与展望”">​</a></h2><p>截至 2026 年 7 月，KossJS 已从最初的一个冲动念头，成长为一个功能完整的 JavaScript 运行时。 它使用 Rust 和 Boa 构建，兼顾性能与可嵌入性，未来将继续迭代，并期待社区用户的反馈与共建。</p>',23)])])}const u=e(a,[["render",i]]);export{h as __pageData,u as default};
